<?php
/**
 * Ticket page tab #history ("Historique détaillé", hidden until its tab is selected):
 * paginated field-level change log with author, date and before/after values; long values
 * and descriptions are folded into <details>. Loads ticket-history.js.
 * Comments and replies from TicketHistory::withConversation() (kind "comment") are interleaved without their
 * content: who wrote, who they answer, and a link to the message; replies branch off the timeline by depth.
 * Included by ticket.php. Expects $ticket and $history (entries, total, limit, offset).
 * $historyActions maps stored action codes to French labels.
 * An edited message (field "comment", action "comment.edited") is shown as a line diff computed by
 * App\Services\TextDiff from the stored plain texts: added lines in green (+), removed lines in red (−).
 */
$historyActions=['updated'=>'Modification','archived'=>'Archivage','restored'=>'Restauration','validation.approved'=>'Validation','validation.rejected'=>'Reprise demandée','time.created'=>'Temps ajouté','time.updated'=>'Temps modifié','time.deleted'=>'Temps supprimé','comment.edited'=>'Message modifié']; ?>
<section id="history" class="panel tracking-panel" data-ticket-panel data-ticket-live aria-labelledby="ticket-tab-history" hidden><div class="panel-header"><div><h2>Historique détaillé</h2><p>Auteur, date et valeurs avant/après chaque modification depuis l’activation du suivi.</p></div><?= icon('clock') ?></div>
<div class="history-timeline">
<?php $previousHistoryDay=''; foreach($history['entries'] as $event): $historyDay=substr($event['created_at'],0,10);$historyActor=$event['actor_name']??'Système / demande externe'; ?>
<?php if(($event['kind']??'change')==='comment'): $historyDepth=min(4,(int)$event['depth']); ?><article class="history-timeline-entry history-comment<?= $historyDepth?' history-reply history-depth-'.$historyDepth:'' ?>" data-history-event><h3 class="history-day" data-history-day <?= $historyDay===$previousHistoryDay?'hidden':'' ?>><?= e($historyDay) ?></h3><div class="history-timeline-row"><span class="history-marker" aria-hidden="true"><?= icon('comment') ?></span><div class="history-event-body"><header><?= avatar($historyActor,'small',$event['actor_id']?(int)$event['actor_id']:null) ?><strong><?= e($historyActor) ?></strong><span class="history-action" data-history-action="<?= $historyDepth?'comment.reply':'comment' ?>"><?= $historyDepth?'Réponse':'Commentaire' ?></span><time datetime="<?= e(str_replace(' ','T',$event['created_at']).'Z') ?>"><?= e($event['created_at']) ?> UTC</time></header><p class="history-comment-route"><?php if($historyDepth): ?>a répondu à <strong><?= e($event['parent_name']) ?></strong><?php if($event['thread_name']): ?> <span>· fil de <?= e($event['thread_name']) ?></span><?php endif; ?><?php else: ?>a ajouté un commentaire<?php endif; ?> <a class="text-button" href="#comment-<?= (int)$event['comment_id'] ?>">Voir le message</a></p></div></div></article>
<?php $previousHistoryDay=$historyDay; continue; endif; ?><article class="history-timeline-entry" data-history-event><h3 class="history-day" data-history-day <?= $historyDay===$previousHistoryDay?'hidden':'' ?>><?= e($historyDay) ?></h3><div class="history-timeline-row"><span class="history-marker" aria-hidden="true"><?= icon(str_starts_with($event['action'],'time.')?'clock':($event['action']==='comment.edited'?'comment':'edit')) ?></span><div class="history-event-body"><header><?= avatar($historyActor,'small',$event['actor_id']?(int)$event['actor_id']:null) ?><strong><?= e($historyActor) ?></strong><span class="history-action" data-history-action="<?= e($event['action']) ?>"><?= e($historyActions[$event['action']]??'Modification') ?></span><time datetime="<?= e(str_replace(' ','T',$event['created_at']).'Z') ?>"><?= e($event['created_at']) ?> UTC</time></header><dl class="history-changes"><?php foreach($event['changes'] as $change): ?><?php if($change['field']==='comment'): $commentDiff=\App\Services\TextDiff::compare((string)$change['before'],(string)$change['after']); ?><div><dt><?= e($change['label']) ?></dt><dd><p class="history-diff-summary"><span class="history-diff-added">+<?= (int)$commentDiff['added'] ?></span> <span class="history-diff-removed">−<?= (int)$commentDiff['removed'] ?></span><?php if(!empty($change['comment_id'])): ?> <a class="text-button" href="#comment-<?= (int)$change['comment_id'] ?>">Voir le message</a><?php endif; ?></p><?php if($commentDiff['truncated']): ?><p class="muted">Les deux versions diffèrent trop pour être comparées ligne à ligne.</p><?php elseif(!$commentDiff['rows'] || !$commentDiff['added'] && !$commentDiff['removed']): ?><p class="muted">Mise en forme modifiée, texte identique.</p><?php else: ?><div class="history-diff" role="table" aria-label="Différences du message"><?php foreach($commentDiff['rows'] as $row): ?><div class="history-diff-row <?= e($row['type']) ?>" role="row"><span class="history-diff-sign" role="cell" aria-label="<?= ['add'=>'Ajoutée','del'=>'Supprimée','same'=>'Identique','gap'=>'Lignes masquées'][$row['type']] ?>"><?= ['add'=>'+','del'=>'−','same'=>'','gap'=>'⋯'][$row['type']] ?></span><span class="history-diff-text" role="cell"><?php if($row['parts']): foreach($row['parts'] as [$changed,$text]): ?><?= $changed?'<mark>'.e($text).'</mark>':e($text) ?><?php endforeach; else: ?><?= e($row['text']) ?><?php endif; ?></span></div><?php endforeach; ?></div><?php endif; ?></dd></div><?php continue; endif; ?><div><dt><?= e($change['label']) ?></dt><dd><?php if($change['field']==='description' || mb_strlen($change['before_label'].$change['after_label'])>500): ?><details><summary>Voir les valeurs</summary><?php endif; ?><div class="history-before"><small>Avant</small><span><?= e($change['before_label']) ?></span></div><div class="history-after"><small>Après</small><span><?= e($change['after_label']) ?></span></div><?php if($change['field']==='description' || mb_strlen($change['before_label'].$change['after_label'])>500): ?></details><?php endif; ?></dd></div><?php endforeach; ?></dl></div></div></article>
<?php $previousHistoryDay=$historyDay; endforeach; if(!$history['entries']): ?><p class="empty-state">Aucune modification enregistrée pour ce ticket.</p><?php endif; ?></div>
<?php if($history['total']>$history['limit']): ?><nav class="pagination" aria-label="Pages de l’historique"><?php if($history['offset']): ?><a class="button subtle" href="<?= e(ticket_url((int)$ticket['id'],'#history',['history_offset'=>max(0,$history['offset']-$history['limit'])])) ?>">Plus récentes</a><?php endif; ?><span><?= $history['offset']+1 ?>–<?= min($history['total'],$history['offset']+$history['limit']) ?> sur <?= $history['total'] ?></span><?php if($history['offset']+$history['limit']<$history['total']): ?><a class="button subtle" href="<?= e(ticket_url((int)$ticket['id'],'#history',['history_offset'=>($history['offset']+$history['limit'])])) ?>">Plus anciennes</a><?php endif; ?></nav><?php endif; ?></section>

<script src="<?= e(asset_url('ticket-history.js')) ?>" defer></script>
